pageCss:
.gc-bench{border:1px solid var(--slate-73);background:var(--row-alt);box-shadow:inset 1px 1px 0 #fff;padding:12px;margin:10px 0 14px}
.gc-presets{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 8px}
.gc-sum{font-size:var(--text-sm);color:var(--slate-30);margin:0 0 10px;font-family:var(--font-mono)}
.gc-guard{border:1px solid var(--slate-82);background:var(--surface-field);padding:8px 10px;margin:0 0 8px}
.gc-head{display:flex;justify-content:space-between;gap:10px;align-items:baseline;flex-wrap:wrap;margin:0 0 4px}
.gc-head b{font-family:var(--font-caption);color:var(--luna-44)}
.gc-cite{font-size:var(--text-micro);color:var(--ink-dim)}
.gc-guard label{display:flex;gap:6px;align-items:baseline;font-size:var(--text-xs);color:var(--slate-30);margin:2px 0}
.gc-runs{display:grid;gap:3px;margin:6px 0 0;font-size:var(--text-xs)}
.gc-run{display:grid;grid-template-columns:84px 44px 1fr;gap:6px;align-items:baseline}
.gc-run .gc-lbl{color:var(--ink-dim)}
.gc-run .gc-res{font-family:var(--font-mono);font-weight:bold}
.gc-run .gc-res.pass{color:var(--green-51)}
.gc-run .gc-res.fail{color:var(--danger-deep)}
.gc-run code{font-size:var(--text-micro);white-space:normal;overflow-wrap:anywhere}
.gc-verdict{margin:6px 0 0;font-size:var(--text-xs);color:var(--slate-30);display:flex;gap:8px;align-items:baseline;flex-wrap:wrap}
.gc-chip{font-family:var(--font-mono);font-size:var(--text-micro);font-weight:bold;letter-spacing:.05em;padding:1px 6px;border:1px solid;border-radius:2px;white-space:nowrap}
.gc-chip.caught{color:var(--green-51);background:var(--green-97)}
.gc-chip.blind{color:var(--danger-deep);background:var(--red-95)}
.gc-chip.wrong,.gc-chip.red{color:var(--warn);background:var(--amber-96)}
.gc-scroll{overflow-x:auto;margin:0 0 12px}
.gc-table{border-collapse:collapse;width:100%;font-size:var(--text-sm)}
.gc-table th,.gc-table td{border:1px solid var(--slate-82);padding:4px 8px;text-align:left;vertical-align:top}
.gc-table thead th{background:var(--slate-92);font-family:var(--font-caption);color:var(--luna-44)}
.gc-table tbody tr:nth-child(even){background:var(--row-alt)}
@media (max-width:520px){.gc-run{grid-template-columns:70px 40px 1fr}}

pageJs:
(function(){
  var bench = document.getElementById("gc-bench");
  if (!bench) return;
  var rows = document.getElementById("gc-rows"), sum = document.getElementById("gc-sum");
  var ok = function(says){ return { fail: false, says: says }; };
  var no = function(says){ return { fail: true, says: says }; };
  var GUARDS = [
    {
      name: "Every Garage page is registered",
      cite: "invariant 8c, a build step",
      drift: "#457: the pages move to src/pages, and the walk still reads public/garage",
      fix: "#1390: count the pages walked and fail under the floor (3 here, 30 of 39 for real)",
      expect: "is not registered",
      run: function(s, planted){
        var disk = { "src/pages/garage": ["ranges.html", "round-trip.html", "av2.html"], "public/garage": ["av2/tile.avif", "lean/proof.svg"] };
        if (planted) disk["src/pages/garage"].push("control-probe.html");
        var dir = s.drift ? "public/garage" : "src/pages/garage";
        var pages = disk[dir].filter(function(f){ return /\.html$/.test(f); });
        var walked = "walked " + pages.length + " pages in " + dir;
        if (s.fix && pages.length < 3) return no(walked + ", under the floor of 3");
        var stray = pages.filter(function(f){ return ["ranges.html", "round-trip.html", "av2.html"].indexOf(f) < 0; });
        if (stray.length) return no("/garage/" + stray[0].replace(".html", "") + " exists on disk but is not registered");
        return ok(walked + ", all registered");
      }
    },
    {
      name: "No conflict marker in a served file",
      cite: "invariant 10, a build step",
      drift: "#523: serendipity becomes TypeScript, and the scan still matches .js",
      fix: "#1390: count the files each root yields and fail at 0",
      bare: true,
      expect: "git conflict marker",
      run: function(s, planted){
        var ext = s.drift ? ".ts" : ".js";
        var files = ["serendipity" + ext, "luma" + ext, "store" + ext];
        if (planted && s.bare) return no("build: Unexpected token '<<' in serendipity" + ext + ", before any scan ran");
        var read = files.filter(function(f){ return /\.js$/.test(f) || !s.drift; });
        if (s.fix && !read.length) return no("serendipity/ yielded 0 files to scan");
        if (planted && read.length) return no("serendipity/" + read[0] + ":12: git conflict marker in a served file");
        return ok("read " + read.length + " of 3 files in serendipity/");
      }
    },
    {
      name: "The taskbar floor agrees across copies",
      cite: "build step 5",
      drift: "#1369: luna.css and the homepage spell the floor through var(--taskbar-h)",
      fix: "#1408: resolve var() through each document, and fail when a copy has no floor",
      expect: "disagrees",
      run: function(s, planted){
        var tok = "calc(100dvh - var(--taskbar-h))", lit = "calc(100dvh - 30px)";
        var copies = [["luna.css", s.drift ? tok : lit], ["index.html", s.drift ? tok : lit], ["cal/src/templates.ts", planted ? "calc(100dvh - 28px)" : lit]];
        var found = [], missing = [];
        copies.forEach(function(c){
          var css = s.fix ? c[1].replace("var(--taskbar-h)", "30px") : c[1];
          var m = /calc\(100dvh - (\d+)px\)/.exec(css);
          if (m) found.push(c[0] + " " + m[1] + "px"); else missing.push(c[0]);
        });
        if (s.fix && missing.length) return no("no taskbar floor in " + missing.join(", "));
        var px = found.map(function(f){ return f.split(" ")[1]; });
        if (px.some(function(p){ return p !== px[0]; })) return no("taskbar-floor disagrees: " + found.join(", "));
        return ok("compared " + found.length + " of 3 copies" + (missing.length ? "; warning: no floor found in " + missing.join(", ") : ""));
      }
    },
    {
      name: "Only index.ts imports cloudflare:workers",
      cite: "gotcha 16, a contract test",
      drift: "the new file isn't git added yet, as on a local run",
      fix: "#1490: list untracked files too, through repoFiles()",
      expect: "imports cloudflare:workers",
      run: function(s, planted){
        // paths are relative to src/worker, where the real control plants lib/control-probe.ts
        var listed = ["index.ts", "lib/preview.ts", "lib/trace.ts"];
        if (planted && (!s.drift || s.fix)) listed.push("lib/control-probe.ts");
        var hit = listed.filter(function(f){ return f === "lib/control-probe.ts"; });
        if (hit.length) return no(hit[0] + " imports cloudflare:workers; only index.ts may");
        return ok("scanned " + listed.length + " files in src/worker from " + (s.fix ? "the index and the worktree" : "git ls-files"));
      }
    }
  ];
  var PRESETS = {
    before: [{ drift: 1 }, { drift: 1 }, { drift: 1 }, { drift: 1 }],
    today: [{ fix: 1 }, { fix: 1 }, { drift: 1, fix: 1 }, { drift: 1, fix: 1 }],
    clean: [{}, {}, {}, {}]
  };
  var state = PRESETS.before.map(function(p){ return { drift: !!p.drift, fix: !!p.fix, bare: false }; });
  var esc = function(t){ return String(t).replace(/[&<>]/g, function(c){ return { "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]; }); };
  var box = function(i, k, label){ return '<label><input type="checkbox" data-i="' + i + '" data-k="' + k + '"' + (state[i][k] ? " checked" : "") + "> " + esc(label) + "</label>"; };
  var line = function(label, r){ return '<div class="gc-run"><span class="gc-lbl">' + label + '</span><span class="gc-res ' + (r.fail ? "fail" : "pass") + '">' + (r.fail ? "FAIL" : "PASS") + "</span><code>" + esc(r.says) + "</code></div>"; };
  function verdict(g, base, planted){
    if (base.fail) return ["red", "RED ON A GOOD TREE", "The harness stops here, since a check that's already red proves nothing. On this bench that's the floor doing its job: the change that blinds the check fails the build it lands in."];
    if (!planted.fail) return ["blind", "BLIND", "It passed with the defect in place. validate shows the good tree, so nobody sees this."];
    if (planted.says.indexOf(g.expect) < 0) return ["wrong", "WRONG REASON", "Red, without the check's own words, so this run says nothing about the check."];
    return ["caught", "CAUGHT", "Red, in the check's own words."];
  }
  function render(){
    var n = { caught: 0, blind: 0, wrong: 0, red: 0 }, green = 0;
    rows.innerHTML = GUARDS.map(function(g, i){
      var s = state[i], base = g.run(s, false), planted = g.run(s, true), v = verdict(g, base, planted);
      n[v[0]]++; if (!base.fail) green++;
      return '<div class="gc-guard"><div class="gc-head"><b>' + esc(g.name) + '</b><span class="gc-cite">' + esc(g.cite) + "</span></div>" +
        box(i, "drift", g.drift) + box(i, "fix", g.fix) + (g.bare ? box(i, "bare", "plant it as bare code, outside a string") : "") +
        '<div class="gc-runs">' + line("good tree", base) + line("planted", planted) + "</div>" +
        '<p class="gc-verdict"><span class="gc-chip ' + v[0] + '">' + v[1] + "</span>" + esc(v[2]) + "</p></div>";
    }).join("");
    sum.textContent = "good tree: " + green + " of 4 pass. planted: " + n.caught + " caught, " + n.blind + " blind, " + n.wrong + " wrong reason" + (n.red ? ", " + n.red + " red before planting" : "") + ".";
  }
  rows.addEventListener("change", function(e){
    var t = e.target;
    if (!t.dataset || t.dataset.i == null) return;
    state[+t.dataset.i][t.dataset.k] = t.checked;
    render();
  });
  bench.querySelectorAll("[data-preset]").forEach(function(b){
    b.addEventListener("click", function(){
      state = PRESETS[b.dataset.preset].map(function(p){ return { drift: !!p.drift, fix: !!p.fix, bare: false }; });
      render();
    });
  });
  render();
})();
